'use strict';
const supplements={pilot:null,acquisition:null,graphStats:null,errors:[],audioQuery:'',audioPublisher:'all',audioPage:1};
async function loadExtensions(){const results=await Promise.allSettled([getJson('new-message-pilot.json'),getJson('acquisition.json'),getJson('claim-graph-statistics.json')]);for(let i=0;i<results.length;i++){const key=['pilot','acquisition','graphStats'][i],r=results[i];if(r.status==='fulfilled')supplements[key]=r.value;else{supplements[key]=null;supplements.errors.push(key+': '+r.reason.message);}}}
function pilotView(){const d=supplements.pilot;if(!d)return '';const docs=arr(d.documents),doc=id=>docs.find(x=>x.source_id===id),pairs=arr(d.pairs).filter(p=>p.comparison_kind==='same_label_cross_medium');return `<section class="section" id="named-label-pilot"><span class="eyebrow">SEPARATE NEW-MESSAGE PILOT</span><div class="section-head"><h2>Shared labels, different human mediums.</h2><p>This pilot uses newly retained publisher message bodies. Its units and model are separate from the joint source-context study above. Pair similarity does not establish a shared entity or equivalent answers.</p></div><div class="metrics"><div><b>${num(d.coverage?.documents)}</b><span>new publisher message documents</span></div><div><b>${num(d.coverage?.words)}</b><span>retained message words</span></div><div><b>${num(pairs.length)}</b><span>same-label / cross-medium pairs</span></div><div><b>${num(d.coverage?.mediums)}</b><span>source-attributed human mediums</span></div></div><div class="scope-note"><p><strong>Questions in the reading comparison are analyst-composed.</strong> They organize interpretation of publisher messages; they are not matched audience questions or verified responses to a shared prompt. Audio/text alignment and independence remain separate checks.</p></div><div class="table-wrap" role="region" tabindex="0" aria-label="Same claimed-label text comparisons"><table class="matrix"><thead><tr><th>Claimed-name comparison</th><th>First source</th><th>Second source</th><th>Full-text TF-IDF</th><th>300-token window</th></tr></thead><tbody>${pairs.map(p=>{const a=doc(p.source),b=doc(p.target);return `<tr><th scope="row">${esc(a?.comparison_label||p.source_label)}<small>${esc(human(p.comparison_level||'comparison level unreported'))} · different medium · no identity equivalence</small></th><td>${esc(a?.medium||p.source_medium)}<small>${link(a?.source_url,a?.title||p.source)}</small></td><td>${esc(b?.medium||p.target_medium)}<small>${link(b?.source_url,b?.title||p.target)}</small></td><td>${num(p.cosine,4)}</td><td>${num(p.window_300_cosine,4)}</td></tr>`;}).join('')||'<tr><td colspan="5">No supported same-label / different-medium pairs in this pilot.</td></tr>'}</tbody></table></div><p class="caption">All scores are text similarity cosines, not probabilities of agreement. Small, selected message sets cannot rank civilizations or establish prevalence.</p>${arr(d.reading?.comparisons).map(c=>`<article class="comparison-row"><h3>${esc(c.question_family||c.comparison_label)}</h3><p class="caption">${esc(human(c.comparison_level||'named written label comparison'))}</p><p><strong>Analytical comparison:</strong> ${esc(c.shared_theme)}</p>${[['natalie_glasson','Natalie Glasson'],['pamela_kribbe','Pamela Kribbe'],['daniel_scranton','Daniel Scranton'],['lyssa_royal','Lyssa Royal Holt']].filter(([key])=>c[key]).map(([key,label])=>`<p><strong>${esc(label)}-attributed message:</strong> ${esc(c[key])}</p>`).join('')}<p><strong>Difference:</strong> ${esc(c.difference)}</p><p><strong>Counterpoint:</strong> ${esc(c.counterpoint)}</p><p><strong>Question / answer status:</strong> ${esc(c.question_answer_status)}</p><div class="analysis-links">${arr(c.source_ids).map(doc).filter(Boolean).map(x=>link(x.source_url,x.medium+' · '+x.title)).join('')}</div></article>`).join('')}<div class="topics">${arr(d.topics).map(t=>`<article class="topic"><h3>Pilot factor ${esc(t.id)}</h3><div class="chips">${arr(t.terms).map(term=>`<span>${esc(term)}</span>`).join('')}</div><p>${esc(t.scope)}</p></article>`).join('')}</div><div class="scope-note"><p>Pilot clustering: k=${num(d.clusters?.k)}, silhouette ${num(d.clusters?.silhouette,4)}, agreement with source-medium grouping (adjusted Rand index) ${num(d.clusters?.source_medium_ARI,4)}. ${esc(d.clusters?.selection)} The low silhouette and source-medium dependence limit interpretation.</p></div>${pilotMaskSensitivity(d)}${arr(d.figures).filter(f=>String(f.file||'').endsWith('.svg')).map(f=>figure({...f,file:'pilot-figures/'+f.file})).join('')}<details><summary>Inspect all new message boundaries and source roles</summary><div class="table-wrap" role="region" tabindex="0" aria-label="New publisher message provenance"><table class="register-table"><thead><tr><th>Publisher message</th><th>Human / claimed label</th><th>Words</th><th>Attribution and boundary</th><th>Audio aligned</th></tr></thead><tbody>${docs.map(x=>`<tr><th scope="row">${link(x.source_url,x.title)}<small>${esc(x.source_id)}</small></th><td>${esc(x.medium)}<small>${esc(x.label)}</small></td><td>${num(x.words)}</td><td>${esc(text(x.attribution_scope))}<small>${esc(text(x.boundary))}</small></td><td>${x.audio_alignment_verified===true?'Verified':'Unverified'}</td></tr>`).join('')}</tbody></table></div></details><ul class="limitations">${arr(d.limitations).map(l=>`<li>${esc(text(l))}</li>`).join('')}</ul><div class="downloads"><a href="new-message-pilot.json" download>Download separate message-pilot analysis JSON</a></div></section>`;}
function audioRows(){const q=supplements.audioQuery.trim().toLowerCase();return arr(supplements.acquisition?.records).filter(r=>(supplements.audioPublisher==='all'||r.publisher_handle===supplements.audioPublisher)&&(!q||[r.publication_id,r.source_id,r.title,r.publisher_handle,r.publisher].join(' ').toLowerCase().includes(q)));}
function audioTable(){const rows=audioRows(),pages=Math.max(1,Math.ceil(rows.length/16));supplements.audioPage=Math.min(supplements.audioPage,pages);return `<div class="result-summary"><p><strong>${num(rows.length)}</strong> receipt-backed retained publication records match. Uncompleted frame entries are not silently counted as retained.</p><button class="secondary" type="button" id="export-audio">Export retained audio metadata</button></div><div class="table-wrap" role="region" tabindex="0" aria-label="Retained publisher audio inventory"><table class="register-table"><thead><tr><th>Publisher recording</th><th>Publisher / origin</th><th>Decoded minutes</th><th>Retained MB</th><th>Text status</th></tr></thead><tbody>${rows.slice((supplements.audioPage-1)*16,supplements.audioPage*16).map(r=>`<tr><th scope="row">${link(r.source_url,r.title)}<small>${esc(r.publication_id)}</small></th><td>${esc(r.publisher_handle)}<small>${esc(human(r.source_origin))}</small></td><td>${num(finite(r.decoded_duration_seconds)?r.decoded_duration_seconds/60:null,2)}</td><td>${num(finite(r.retained_bytes)?r.retained_bytes/1e6:null,2)}</td><td>${r.local_asr_completed?'Local ASR complete':r.publisher_caption_linked?'Publisher caption linked':r.publisher_written_message_linked?'Publisher written message linked':'No linked text yet'}<small>Audio/text alignment: ${r.audio_text_alignment_verified===true?'verified':'unverified'}<br>In previous frozen fits: ${r.analyzed_in_existing_frozen_fits===true?'yes':'no'}</small></td></tr>`).join('')||'<tr><td colspan="5">No retained audio records match the current filters.</td></tr>'}</tbody></table></div><div class="pager audio-pager"><button class="secondary" type="button" data-audio-page="${supplements.audioPage-1}" ${supplements.audioPage<=1?'disabled':''}>Previous</button><span>Page ${supplements.audioPage} of ${pages}</span><button class="secondary" type="button" data-audio-page="${supplements.audioPage+1}" ${supplements.audioPage>=pages?'disabled':''}>Next</button></div>`;}
function acquisitionView(){const d=supplements.acquisition;if(!d)return '';const s=d.summary||{},f=d.frame||{},channels=arr(d.channels);return `<section class="section" id="publisher-audio"><span class="eyebrow">NEW PUBLISHER-AUDIO COLLECTION</span><div class="section-head"><h2>Audio retained in the workspace.</h2><p>${esc(d.scope)} Snapshot: ${esc(d.generated_at)} · status: <strong>${esc(human(d.status))}</strong>. This is a saved receipt snapshot, not live progress.</p></div><div class="metrics"><div><b>${num(s.completed_publications)}</b><span>retained publisher publications</span></div><div><b>${num(f.total_entries)}</b><span>entries in the finite discovery frame</span></div><div><b>${num(finite(s.retained_bytes)?s.retained_bytes/1e6:null,1)}</b><span>MB of retained audio</span></div><div><b>${num(finite(s.decoded_duration_seconds)?s.decoded_duration_seconds/3600:null,2)}</b><span>decoded audio hours retained</span></div></div><div class="scope-note"><p>Full-duration audio is retained as verified lossy Opus derivatives. Original bytes are hashed before newly staged originals are removed. Linked captions or publisher messages are not automatically verified audio transcripts, and new ASR does not enter earlier frozen analysis fits.</p><p>Total channel uploads and complete historical publisher episode totals remain <strong>unknown</strong>. This frame contains ${num(f.publisher_rss_entries)} RSS entries and ${num(f.publisher_download_page_entries)} publisher download-page entries.</p></div><div class="table-wrap" role="region" tabindex="0" aria-label="Publisher audio storage distribution"><table><thead><tr><th>Publisher / account</th><th>Retained publications</th><th>Audio MB</th><th>Decoded hours</th><th>Caption-linked</th><th>Local ASR</th></tr></thead><tbody>${channels.map(c=>{const m=c.related_publisher_material||{};return `<tr><th scope="row">${esc(c.id)}</th><td>${num(m.current_new_audio_sources_retained)}</td><td>${num(finite(m.current_new_audio_retained_bytes)?m.current_new_audio_retained_bytes/1e6:null,1)}</td><td>${num(finite(m.current_new_audio_decoded_seconds)?m.current_new_audio_decoded_seconds/3600:null,2)}</td><td>${num(m.current_new_audio_caption_linked)}</td><td>${num(m.current_new_audio_local_asr)}</td></tr>`;}).join('')}</tbody></table></div><form class="toolbar"><label class="search">Search retained recordings<input type="search" id="audio-query" value="${esc(supplements.audioQuery)}" placeholder="Title, source ID or publisher"></label><label>Publisher<select id="audio-publisher"><option value="all">All retained publishers</option>${unique(arr(d.records).map(r=>r.publisher_handle)).sort().map(p=>`<option value="${esc(p)}" ${p===supplements.audioPublisher?'selected':''}>${esc(p)}</option>`).join('')}</select></label><button type="button" id="clear-audio" class="secondary">Clear audio filters</button></form><div id="audio-results">${audioTable()}</div><ul class="limitations">${arr(d.limitations).map(l=>`<li>${esc(text(l))}</li>`).join('')}</ul><div class="downloads"><a href="acquisition.json" download>Download publisher-audio acquisition receipts</a></div></section>`;}
document.addEventListener('input',e=>{if(e.target.id==='audio-query'){supplements.audioQuery=e.target.value;supplements.audioPage=1;$('#audio-results').innerHTML=audioTable();announce(audioRows().length+' retained audio records match.');}});
document.addEventListener('change',e=>{if(e.target.id==='audio-publisher'){supplements.audioPublisher=e.target.value;supplements.audioPage=1;$('#audio-results').innerHTML=audioTable();announce(audioRows().length+' retained audio records match.');}});
document.addEventListener('click',e=>{if(e.target.id==='clear-audio'){Object.assign(supplements,{audioQuery:'',audioPublisher:'all',audioPage:1});$('#publisher-audio').outerHTML=acquisitionView();$('#audio-query').focus();}const b=e.target.closest('[data-audio-page]');if(b&&!b.disabled){supplements.audioPage=Number(b.dataset.audioPage);$('#audio-results').innerHTML=audioTable();($('#audio-results .pager button:last-child:not(:disabled)')||$('#audio-results .pager button:first-child:not(:disabled)'))?.focus();}if(e.target.id==='export-audio'){const headers=['publication_id','source_id','title','publisher_handle','source_origin','source_url','collection_status','retained_bytes','decoded_duration_seconds','local_asr_completed','publisher_caption_linked','publisher_written_message_linked','audio_text_alignment_verified','retained_sha256','original_sha256'];exportCsv('publisher-audio-acquisition.csv',headers,audioRows().map(r=>headers.map(k=>r[k])));}});

function pilotMaskSensitivity(d){const s=d.phrase_mask_sensitivity;if(!s)return '';return `<section class="section"><h3>Does council-name wording explain the pattern?</h3><p class="caption">Original masking is partial: some title words remain in topic factors. This separate check removes declared full council-title phrases, then refits TF-IDF on the same messages. It is a preprocessing sensitivity, not independent validation.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Full title phrase masking sensitivity"><table><thead><tr><th>Pair type</th><th>Dependent pairs</th><th>Original mean cosine</th><th>Full-title-mask mean cosine</th></tr></thead><tbody>${arr(s.pair_summary).map(r=>`<tr><th scope="row">${esc(human(r.kind))}</th><td>${num(r.pairs)}</td><td>${num(r.original_mean_cosine,5)}</td><td>${num(r.phrase_mask_mean_cosine,5)}</td></tr>`).join('')}</tbody></table></div><p class="caption">Maximum change for any pair: ${num(s.maximum_pair_cosine_change,5)}. ${esc(s.scope)}</p></section>`;}
function groupPilotCoverage(g){const r=arr(supplements.graphStats?.comparison_groups).find(x=>x.id===g.id);return r?`${num(r.new_attributed_message_documents)} message documents<small>${num(r.new_attributed_message_mediums)} source-attributed mediums · ${esc(human(r.text_comparison_status))}</small>`:'No matched pilot-coverage record';}
